            "You should manually check whether the generated output is acceptable for those " +
            "older devices.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private static final String ANDROID_URI = "http://schemas.android.com/apk/res/android";
    private static final String AAPT_URI = "http://schemas.android.com/aapt";
    private static final int MAX_SIZE_DP = 200;

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList("vector", "path", "gradient");
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (context.getResourceFolderType() != ResourceFolderType.DRAWABLE) {
            return;
        }

        String tag = element.getTagName();

        if ("vector".equals(tag)) {
            checkVectorSize(context, element);
        } else if ("gradient".equals(tag)) {
