            Attr aaptAttr = element.getAttributeNodeNS(AAPT_URI, "attr");
            if (aaptAttr != null) {
                context.report(ISSUE, aaptAttr, context.getLocation(aaptAttr),
                        "aapt:attr is not fully supported in vector rasterization for older devices");
            }
        }
    }

    private void checkVectorSize(XmlContext context, Element element) {
        String widthStr = element.getAttributeNS(ANDROID_URI, "width");
        String heightStr = element.getAttributeNS(ANDROID_URI, "height");

        float width = parseDimension(widthStr);
        float height = parseDimension(heightStr);

        if (width > MAX_SIZE_DP || height > MAX_SIZE_DP) {
            String message = String.format(
                    "Vector icons should not be larger than %1$dx%1$d dp; this icon is %2$.0fx%3$.0f dp",
                    MAX_SIZE_DP, width, height);
            context.report(ISSUE, element, context.getLocation(element), message);
        }
    }

    private static float parseDimension(String value) {
        if (value == null || value.isEmpty()) {
            return 0f;
        }
        if (value.endsWith("dp")) {
            try {
                return Float.parseFloat(value.substring(0, value.length() - 2));
            } catch (NumberFormatException e) {
                return 0f;
            }
        }
        return 0f;
    }
}
